'use strict';
const $=id=>document.getElementById(id),data=window.SHANHE_DATA,engine=window.createShanheEngine(data);window.gameEngine=engine;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=engine.fresh(),loadNote='';try{const saved=localStorage.getItem('shanhe-save-v2')||localStorage.getItem('shanhe-save-v1');if(saved){state=engine.migrate(JSON.parse(saved));loadNote='已续入上次行记';}}catch{loadNote='存档无法读取，已开启新行记。旧存档未删除。';}
let selected=state.loc,atlas=null,autoTimer=null,currentView=null,cityTab='府衙',collapsed=false,saveBlocked=false;
const ranks=['在野游士','从事','军司马'];const date=()=>`${190+Math.floor(state.day/360)}年 ${Math.floor(state.day%360/30)+1}月${state.day%30+1}日`;
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(manual=false){try{localStorage.setItem('shanhe-save-v2',JSON.stringify(state));$('saveStatus').textContent='行记已保存';$('saveStatus').classList.add('saving');saveBlocked=false;if(manual)toast('已保存到此浏览器，下次可继续。');}catch{$('saveStatus').textContent='未能保存';if(manual||!saveBlocked)toast('浏览器未允许本机保存，请保持页面开启。');saveBlocked=true;}}
function pause(){if(autoTimer)clearInterval(autoTimer);autoTimer=null;$('auto').textContent='▶ 继续';$('auto').setAttribute('aria-pressed','false');}
function show(view){pause();currentView=view;renderDialog();if(!$('dialog').open)$('dialog').showModal();}
function doAction(action,input={}){const result=engine.execute(state,action,input);if(!result.ok){toast(result.message);return result;}if(result.milestone)pause();save();render();if(currentView&&$('dialog').open)renderDialog();if(action!=='day'||result.milestone)toast(result.message);return result;}
function selectCity(id,focus=false){selected=id;collapsed=false;render();if(focus)atlas.focus(id,true);else atlas.select(id);}
function button(label,action,extra='',disabled=false){return `<button ${disabled?'disabled':''} data-action="${action}" ${extra}>${label}</button>`;}
function render(){const c=data.cities[selected],here=selected===state.loc&&!state.travel;const town=state.towns[selected];$('date').textContent=date();$('money').textContent=Math.floor(state.money);$('fame').textContent=state.fame;$('energy').textContent=state.energy;$('rank').textContent=`${state.faction?state.faction+' · ':''}${ranks[state.rank]}`;$('playerPlace').textContent=state.travel?`行往${data.cities[state.travel.target].name}`:`现居 · ${data.cities[state.loc].name}`;$('region').textContent=`${c.region} / ${here?'身在此地':'城池情报'}`;$('cityName').textContent=c.name;$('owner').textContent=c.owner;$('owner').style.borderColor=data.colors[c.owner]||'#9b8058';$('cityDesc').textContent=c.desc;$('public').textContent=Math.round(town.public);$('troops').textContent=(town.troops/10000).toFixed(1)+'万';$('npcCount').textContent=c.npcs.length;$('cityBody').hidden=collapsed;$('collapseCity').textContent=collapsed?'＋':'−';$('collapseCity').setAttribute('aria-expanded',String(!collapsed));
  if(state.travel){$('cityAction').innerHTML=`<p class="route">正前往${esc(data.cities[state.travel.target].name)}<br>已行 ${state.travel.elapsed} / ${state.travel.total} 日</p>${button('沿途停留','stopTravel')}`;}else if(here){$('cityAction').innerHTML='<button class="primary" data-ui="enter">进入城中 <span>→</span></button><p class="muted">府衙受托 · 宅邸访友 · 客舍休整</p>';}else{const p=engine.route(state.loc,selected);$('cityAction').innerHTML=`<div class="route">${p.nodes.map(i=>esc(data.cities[i].name)).join(' → ')}</div><div class="route-cost"><span>路程约 ${p.km} 公里</span><span>${p.days} 日 · ${p.cost} 钱</span></div><button class="primary" data-action="depart" data-city="${selected}" ${state.energy<15||state.money<p.cost||state.battle?'disabled':''}>启程前往 <span>→</span></button><p class="muted">${state.energy<15?'体力不足15，请先休整。':state.money<p.cost?'盘缠不足，可在当地承接委托。':'需体力15，途中时间由你推进。'}</p>`;}
  const job=state.job;$('taskBadge').hidden=!job;$('taskTracker').innerHTML=job?`<div class="eyebrow"><span>受托之事</span><span>余 ${Math.max(0,job.deadline-state.day)} 日</span></div><b>${esc(engine.jobs[job.type].name)}</b><progress value="${job.progress}" max="${engine.jobs[job.type].total}"></progress><p>${esc(data.cities[job.city].name)} · ${esc(job.sponsor)}${job.helper?' · '+esc(job.helper)+'协作':''}</p><button data-ui="tasks">查看委托 ${job.progress}/${engine.jobs[job.type].total} →</button>`:`<div class="eyebrow"><span>${state.rank?'仕途所向':'此生初志'}</span><span>卷一</span></div><b>${state.rank===2?'护境安民，广结同道':state.rank===1?'积累功绩，参与评定':'立足襄阳，求一知己'}</b><p>${state.rank===2?'继续游历或承接委托，经营自己的人生。':state.rank===1?'完成公务积功；功绩20可提案整训，30可请命护粮。':'先承接一桩府衙委托，拜访委托人，逐渐获得举荐。'}</p><button data-ui="${state.rank?'person':'enter'}">${state.rank?'查看人物与功绩':'去城中看看'} →</button>`;
  $('activityTitle').textContent=state.battle?'护粮战事 · 等待军令':state.travel?`行旅中 · ${data.cities[state.travel.target].name}`:job?`受托 · ${engine.jobs[job.type].name}`:`${data.cities[state.loc].name} · 尚无在办之事`;$('activityDetail').textContent=state.travel?`${state.travel.elapsed}/${state.travel.total} 日 · 抵达时自动暂停`:job?`进度 ${job.progress}/${engine.jobs[job.type].total} · 在城中执行任务`:'日常行动自动计时，空闲时可自由推进';$('enter').textContent=state.battle?'返回战局 →':state.travel?'查看行程 →':`进入${data.cities[state.loc].name} →`;$('next').disabled=!!state.battle;$('auto').disabled=!!state.battle;if(atlas)atlas.select(selected);
}
function heading(title,desc=''){return `<div class="dialog-heading"><div><h2>${esc(title)}</h2><p>${esc(desc)}</p></div></div>`;}
function actionMeta(text){return `<div class="meta">${text}</div>`;}
function jobCards(){if(state.job)return activeJob();const c=data.cities[state.loc],foreign=state.rank&&c.owner!==state.faction;return `<div class="cards">${Object.entries(engine.jobs).map(([type,j])=>{const locked=foreign||(type==='train'&&(!state.rank||state.council!=='train'));return `<article class="card"><div class="eyebrow">${esc(c.npcs[j.sponsor%c.npcs.length])} · 委托</div><h3>${j.name}</h3><p>${j.desc}</p>${actionMeta(`<span>期限 ${j.deadline} 日</span><span>报酬 ${j.pay} 钱</span><span>名望 +${j.fame}</span>${state.rank?`<span>功绩 +${j.merit}</span>`:''}`)}${button('领取委托','accept',`data-type="${type}"`,locked)}${locked?`<p class="muted">${foreign?'他方公务不对本势力官员开放。':'需仕官后在评定获准整训提案。'}</p>`:''}</article>`;}).join('')}</div><div class="hint">领取不耗时。亲自执行需要3日；共同完成委托能增进交情，并真实改善城池。休息、等待和旅行只计时间，不会自动增加功绩。</div>`;}
function activeJob(){const j=state.job,d=engine.jobs[j.type],local=j.city===state.loc&&!state.travel;const progress=Math.min(j.progress,d.total);return `${heading(d.name,`${data.cities[j.city].name} · ${j.sponsor}托付`)}<p>${d.desc}</p><div class="project-progress"><span>已完成 ${progress} / ${d.total}</span><span>期限剩余 ${Math.max(0,j.deadline-state.day)} 日</span></div><div class="meter"><span style="width:${progress/d.total*100}%"></span></div><div class="cards"><article class="card"><h3>亲自执行</h3><p>${j.helper?esc(j.helper)+'与你分工，每次额外推进14。':'独自执行，进度取决于你的能力。'}</p>${actionMeta(`<span>3 日</span><span>体力 ${d.energy}</span><span>报酬 ${d.pay} 钱</span>`)}${button('执行委托','work','class="primary"',!local||state.energy<d.energy||state.day+d.days>j.deadline)}<p class="muted">${!local?'请回到委托所在地。':state.energy<d.energy?'体力不足，请先到客舍休整。':state.day+d.days>j.deadline?'期限不足一次执行，可辞去后重新承接。':'完成后自动领取报酬与关系奖励。'}</p></article><article class="card"><h3>邀友相助</h3><p>${j.helper?'当前同伴：'+esc(j.helper):'交情15以上的当地人物可受邀协作。'}</p>${data.cities[j.city].npcs.map(n=>button(`${esc(n)} · 交情${state.friends[n]||0}`,'assist',`data-npc="${esc(n)}" class="npc-choice"`,!local||!!j.helper||(state.friends[n]||0)<15)).join('')}</article></div><div class="button-row">${button('去客舍休整','rest','',!!state.travel)}<button data-ui="abandon">辞去委托</button></div>`;}
function npcCards(){const c=data.cities[state.loc];return `<div class="cards">${c.npcs.map(name=>{const n=engine.npcs[name],relation=state.friends[name]||0;return `<article class="card npc-card"><div class="npc-monogram">${esc(name[0])}</div><div><h3>${esc(name)}</h3><span class="badge">${relation>=40?'相知':relation>=15?'相识':'初识'} · 交情 ${relation}</span><p>${n.intro}</p><div class="meta">拜访 1日 · 体力8 · 喜谈${n.topic}</div><div class="button-row">${['经义','民生','兵略'].map(topic=>button(`谈${topic}`,'visit',`data-npc="${esc(name)}" data-topic="${topic}"`,state.energy<8)).join('')}</div></div></article>`;}).join('')}</div><p class="hint">同一话题八日内反复拜访，收获会减少。完成对方的委托可增加交情12；受邀协作的友人另增交情8。</p>`;}
function councilView(){const c=data.cities[state.loc],sponsor=c.npcs.find(n=>(state.friends[n]||0)>=20);if(!state.rank)return `<article class="card"><div class="eyebrow">由布衣而入仕</div><h3>寻求举荐</h3><p>需要名望25、当地人物交情20，并完成一桩本地委托。故人愿意为你的品行与能力作保，府衙才会接纳。</p><div class="stat-grid"><div>名望<b>${state.fame}/25</b></div><div>本地委托<b>${state.completed[state.loc]||0}/1</b></div><div>举荐人<b style="font:17px var(--serif)">${sponsor?esc(sponsor):'尚无'}</b></div></div>${button('请故人举荐','join','class="primary"',state.fame<25||!sponsor||!(state.completed[state.loc]>=1))}</article>`;return `<div class="hint">${esc(state.faction)}麾下 · ${ranks[state.rank]} · 功绩 ${state.merit}。${c.owner!==state.faction?'你身在他方，请回本势力参与评定。':'先提出方向，获准后领取相应委托。'}</div><div class="cards"><article class="card"><div class="eyebrow">评定提案</div><h3>安抚乡里</h3><p>建议优先救济乡民，稳定民心。</p>${actionMeta('<span>评定 1日</span><span>在办委托需先结清</span>')}${button('提案安民','council','data-proposal="relief"',!!state.job||c.owner!==state.faction)}</article><article class="card"><div class="eyebrow">评定提案</div><h3>整训乡勇</h3><p>增募守备之兵，解锁整训任务。完成可得功绩22。</p>${actionMeta('<span>功绩20</span><span>评定1日</span>')}${button('提案整训','council','data-proposal="train"',state.merit<20||!!state.job||c.owner!==state.faction)}</article><article class="card"><div class="eyebrow">军务请命</div><h3>护卫粮道</h3><p>率乡勇五百，运用坚守、迂回与激励击退盗寇。</p>${actionMeta('<span>功绩30</span><span>体力30</span><span>需结清在办委托</span>')}${button('请命出征','campaign','class="primary"',state.merit<30||state.energy<30||!!state.job||c.owner!==state.faction)}</article></div>`;}
function battleView(){if(!state.battle)return `${heading(state.rank===2?'护粮告捷':'整备再战')}<p>${esc(state.logs[0]?.text||'战斗已经结束。')}</p><button data-ui="enter" class="primary">返回城中</button>`;const b=state.battle;return `${heading('粮道遭遇战',`第${b.round+1}回合 · 每道军令推进一日`)}<div class="battle-grid"><div class="army"><div class="eyebrow">我军 · 沈行舟</div><h3>乡勇 ${b.troops}</h3><p>士气 ${Math.max(0,b.morale)} / 100</p><div class="meter"><span style="width:${Math.max(0,b.morale)}%"></span></div><p>可用指挥 <b>${b.command}</b> / 5</p></div><div class="army"><div class="eyebrow">敌军 · 盗寇</div><h3>兵力 ${b.enemy}</h3><p>士气 ${Math.max(0,b.enemyMorale)} / 100</p><div class="meter"><span style="background:#9e5e48;width:${Math.max(0,b.enemyMorale)}%"></span></div><p>山道狭窄，敌军难以展开。</p></div></div><div class="button-row">${button('坚守 · 恢复指挥1','battleChoice','data-choice="guard"')}${button('迂回 · 指挥2','battleChoice','data-choice="flank"',b.command<2)}${button('激励 · 指挥2','battleChoice','data-choice="rally"',b.command<2)}</div><p class="hint">坚守依统率削弱敌军，迂回依智略打击士气，激励恢复本方士气。敌军士气或兵力归零则获胜；本方溃散或七回合未决则撤退。</p>`;}
function renderDialog(){let html='';if(currentView==='city'){const c=data.cities[state.loc];if(state.travel){currentView='travel';return renderDialog();}html=`${heading(c.name,`${c.region} · ${c.owner}治下 · 你的行动将改变城池`)}<nav class="city-tabs" aria-label="城内地点">${['府衙','宅邸','客舍','议事'].map(t=>`<button data-tab="${t}" class="${cityTab===t?'active':''}" aria-pressed="${cityTab===t}">${t}</button>`).join('')}</nav>`;if(cityTab==='府衙')html+=jobCards();if(cityTab==='宅邸')html+=npcCards();if(cityTab==='议事')html+=councilView();if(cityTab==='客舍')html+=`<div class="cards"><article class="card"><div class="eyebrow">客舍</div><h3>歇脚养神</h3><p>整理行装，在客舍歇息。休整也会推进委托期限。</p>${actionMeta('<span>3日</span><span>体力+38</span><span>不耗盘缠</span>')}${button('休整三日','rest','class="primary"')}</article><article class="card"><div class="eyebrow">学舍</div><h3>研习兵法</h3><p>统率+3，智略+2。所学将用于委托与战斗。</p>${actionMeta('<span>3日</span><span>50钱</span><span>体力15</span>')}${button('研习三日','study','',state.money<50||state.energy<15)}</article></div>`;}
  if(currentView==='cities')html=heading('天下郡邑录',`${data.cities.length} 座城邑 · ${data.routes.length} 段道路 · 选择城池查看路线`)+`<div class="city-filters"><input id="directoryQuery" type="search" placeholder="输入城名、别名或势力" aria-label="搜索城邑"><select id="directoryRegion" aria-label="按州筛选"><option value="">天下诸州</option>${[...new Set(data.cities.map(c=>c.region))].map(r=>`<option>${esc(r)}</option>`).join('')}</select></div><p id="directoryCount" class="muted"></p><div id="directoryResults" class="city-directory"></div><p class="hint">远近均保留城邑图标；文字会避让，悬停可查看完整城名。新增主簿与乡老为虚构角色，城址来源可在城池详情查看。</p>`;
  if(currentView==='tasks')html=state.job?activeJob():`${heading('委托簿','尚无在办委托')}<p class="empty">到所在城池府衙领取一桩委托吧。</p><button class="primary" data-ui="enter">前往城中</button>`;
  if(currentView==='person')html=`${heading('沈行舟',`${state.faction||'四海为家'} · ${ranks[state.rank]}`)}<div class="stat-grid"><div>统率<b>${state.lead}</b></div><div>武力<b>68</b></div><div>智略<b>${state.wit}</b></div><div>政务<b>61</b></div></div><div class="cards"><article class="card"><h3>仕途与声名</h3><p>名望 ${state.fame} · 功绩 ${state.merit}<br>完成委托 ${Object.values(state.completed).reduce((a,b)=>a+Number(b),0)} 桩 · 护粮获胜 ${state.victories} 次</p></article><article class="card"><h3>今后所向</h3><p>${state.rank===0?'可游历四方、办事交友。愿入仕时，再请当地故人举荐。':state.rank===1?'功绩20可提案整训，30可请求护粮。身份使你获得公务与军务权限。':'已获军司马之职。可继续办理公务、磨练本领与结交各地人物。'}</p></article></div>`;
  if(currentView==='relations')html=`${heading('故人名录','关系由交谈与共同经历积累')}<div class="cards">${Object.entries(state.friends).filter(([,v])=>v>0).map(([n,v])=>`<article class="card"><h3>${esc(n)}</h3><p>交情 ${esc(v)} · ${v>=40?'相知':v>=15?'相识':'初识'}</p><p>${engine.npcs[n]?esc(data.cities[engine.npcs[n].city].name)+' · 喜谈'+engine.npcs[n].topic:'旧识，暂无可拜访地点'}</p>${engine.npcs[n]?`<button data-find="${engine.npcs[n].city}">在地图上寻访</button>`:''}</article>`).join('')||'<p class="empty">尚未结识故人，先到城中宅邸拜访吧。</p>'}</div>`;
  if(currentView==='journal')html=`${heading('随行笔录','记下这一路的选择与经历')}<div>${state.logs.map(l=>`<div class="journal-entry"><time>第${l.day+1}日</time>${esc(l.text)}</div>`).join('')}</div>`;
  if(currentView==='travel'){const t=state.travel;html=heading('行旅途中',t?`正前往${data.cities[t.target].name}`:'已抵达城池');if(t)html+=`<p>${t.nodes.map(i=>esc(data.cities[i].name)).join(' → ')}</p><div class="meter"><span style="width:${t.elapsed/t.total*100}%"></span></div><p>已行${t.elapsed}日 / 预计${t.total}日。抵达将自动暂停。</p><p class="hint">关闭此窗后，点击底部「继续」自动推进，或「过一日」手动推进。委托期限也会随行程流逝。</p>${button('在最近经过城池停留','stopTravel')}`;else html+='<button class="primary" data-ui="enter">进入城中</button>';}
  if(currentView==='battle')html=battleView();
  if(currentView==='geo'){const c=data.cities[selected];html=`${heading(c.name+' · 城址考据',c.historical)}<p>参考点：东经 ${c.lon.toFixed(4)}°，北纬 ${c.lat.toFixed(4)}°。</p><p>${esc(c.geoNote)}</p><p><a href="${esc(c.source)}" target="_blank" rel="noopener">查看原始记录 ↗</a></p><div class="hint">城池使用统一经纬度投影，不再以屏幕像素猜位置。部分郡名按候选治所定位；城名保留常用游戏称呼，许县、秣陵、鱼复已按开局时代调整。坐标不是古城范围的精确复原。</div>`;}
  if(currentView==='help')html=`${heading('行走三国','地图 · 人物 · 委托')}<p><a href="lab/index.html">进入荆襄三维验证样区 →</a></p><p>从襄阳起步：进入城中领取「赈济乡里」，去宅邸拜访委托人，再返回府衙执行。名望25、当地交情20，并完成一桩委托后，可在议事中寻求举荐。</p><p>入仕后完成公务积功，功绩20可提案整训，30可请命护粮。交情15可邀请当地人物协助委托。每次行动会清楚标明耗时和消耗。</p><p>地图可拖动、滚轮或双指缩放；键盘聚焦地图后可用方向键与加减键。寻城菜单可直接定位。旅行启程后点击「继续」，抵达自动暂停。</p><p>行动后自动保存到本浏览器，也可手动保存。旧版行记可迁移。游戏使用每月30日、每年360日的简化历法。</p><div class="hint">势力图按当前城池归属生成连续色块，相邻异势力以虚线分界；海面与湖面不染色，远离城邑地区留白，并非历史疆界复原。此为演义沙盘：人物、势力归属和事件仍为试玩配置，尚无全国势力自动征战。林地、田畴、草地与荒漠为风物示意，可用「风物」开关隐藏。太湖、鄱阳湖、巢湖、青海湖的轮廓来自 Natural Earth 现代湖泊数据；不代表汉末湖岸。海岸与大部分水系为现代地理概化参考，山脉分布与道路为设计示意，不表示汉末河道、疆界或历史行军线。</div><div class="source-list"><a href="https://chgis.fas.harvard.edu/" target="_blank" rel="noopener">历史城址参考：CHGIS（哈佛／复旦）</a><br><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">海岸与水系：Natural Earth，公共领域</a><br>晋阳使用公开遗址参考点；各城详情可查看单独来源。</div><div class="button-row"><button data-ui="new">新建行记</button></div>`;
  if(currentView==='new')html=`${heading('另起一卷')}<p>新行记将从襄阳重新开始。当前行记会先保留一份本机备份，随后更新自动存档。</p><button class="primary" data-ui="reset">备份并新建行记</button>`;
  if(currentView==='abandon')html=`${heading('辞去这桩托付？')}<p>当前进度将结束，不领取报酬；之后可以重新承接委托。</p>${button('确认辞去','abandon')}`;
  $('dialogContent').innerHTML=html;if(currentView==='cities'){renderDirectory();$('directoryQuery').oninput=renderDirectory;$('directoryRegion').onchange=renderDirectory;}
}
function renderDirectory(){const q=$('directoryQuery').value.trim(),region=$('directoryRegion').value;const matches=data.cities.filter(c=>(!region||c.region===region)&&(!q||[c.name,c.alias,c.historical,c.owner].some(v=>v?.includes(q))));$('directoryCount').textContent=`共 ${matches.length} 座城邑`;$('directoryResults').innerHTML=matches.map(c=>`<button data-find="${c.id}"><b>${esc(c.name)}</b><span>${esc(c.region)} · ${esc(c.owner)}</span><small>${c.id===state.loc?'当前所在':c.tier===1?'重镇':c.tier===2?'郡邑':'县城'}</small></button>`).join('')||'<p class="empty">未找到城邑，试试其他城名或州名。</p>';}
function ui(action){if(action==='enter'){if(state.battle)show('battle');else if(state.travel)show('travel');else show('city');}else if(action==='reset'){try{localStorage.setItem('shanhe-save-backup',JSON.stringify(state));}catch{return toast('未能备份当前行记，已取消新建。');}state=engine.fresh();selected=0;save();$('dialog').close();currentView=null;render();atlas.focus(0);toast('新行记已展开。');}else show(action);}
$('dialog').addEventListener('close',()=>{currentView=null});$('closeDialog').onclick=()=>$('dialog').close();document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.ui){ui(b.dataset.ui);return;}if(b.dataset.tab){cityTab=b.dataset.tab;renderDialog();return;}if(b.dataset.find!==undefined){$('dialog').close();selectCity(Number(b.dataset.find),true);return;}if(b.dataset.action){const input={city:Number(b.dataset.city),type:b.dataset.type,npc:b.dataset.npc,topic:b.dataset.topic,proposal:b.dataset.proposal,choice:b.dataset.choice};const result=doAction(b.dataset.action,input);if(result.ok){if(b.dataset.action==='depart'){$('dialog').close();pause();}if(b.dataset.action==='campaign')show('battle');if(b.dataset.action==='abandon')show('tasks');if(b.dataset.action==='join'){cityTab='议事';show('city');}}}});
$('personNav').onclick=()=>show('person');$('relationsNav').onclick=()=>show('relations');$('tasksNav').onclick=()=>show('tasks');$('journalNav').onclick=()=>show('journal');$('help').onclick=()=>show('help');$('geoInfo').onclick=()=>show('geo');$('save').onclick=()=>save(true);$('enter').onclick=()=>ui('enter');$('collapseCity').onclick=()=>{collapsed=!collapsed;render()};$('next').onclick=()=>doAction('day');$('auto').onclick=()=>{if(autoTimer){pause();return;}if(state.battle)return;autoTimer=setInterval(()=>{const r=doAction('day');if(!r.ok)pause();},Number($('speed').value));$('auto').textContent='Ⅱ 暂停';$('auto').setAttribute('aria-pressed','true');};$('speed').onchange=()=>{if(autoTimer){pause();$('auto').click();}};
$('citySearch').innerHTML=`<option value="">寻城 · ${data.cities.length} 郡邑</option>`+[...new Set(data.cities.map(c=>c.region))].map(r=>`<optgroup label="${r}">${data.cities.filter(c=>c.region===r).map(c=>`<option value="${c.id}">${c.name}${c.alias!==c.name?'（'+c.alias+'）':''}</option>`).join('')}</optgroup>`).join('');$('citySearch').onchange=e=>{if(e.target.value!=='')selectCity(Number(e.target.value),true)};
render();atlas=window.createAtlas($('map'),data,()=>state,id=>selectCity(id));atlas.select(selected);$('center').onclick=()=>selectCity(state.loc,true);$('fit').onclick=()=>atlas.fit();$('zoomIn').onclick=()=>atlas.zoom(1.25);$('zoomOut').onclick=()=>atlas.zoom(.8);document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-layer]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});atlas.layer(b.dataset.layer);$('factionLegend').hidden=b.dataset.layer!=='factions';$('taskTracker').hidden=b.dataset.layer==='factions'});$('ecologyToggle').onclick=()=>{const b=$('ecologyToggle'),on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));b.classList.toggle('active',on);atlas.ecology(on)};if(loadNote)toast(loadNote);
if(document.modelContext?.registerTool){for(const tool of [{name:'select_city',description:'选择并定位城池，只查看情报，不移动角色或推进时间。',inputSchema:{type:'object',properties:{city:{type:'string'}},required:['city'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({city})=>{const c=data.cities.find(c=>c.name===city||c.alias===city);if(!c)throw new Error('未知城池');selectCity(c.id,true);return{selected:c.name,current:data.cities[state.loc].name,longitude:c.lon,latitude:c.lat};}}])try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}

$('factionLegend').innerHTML='<div class="eyebrow">天下势力 · 城邑归属</div><div class="faction-keys">'+[...new Set(data.cities.map(c=>c.owner))].map(owner=>'<span><i style="background:'+data.colors[owner]+'"></i>'+esc(owner)+'<small>'+data.cities.filter(c=>c.owner===owner).length+'</small></span>').join('')+'</div><p>城池归属生成的疆域示意<br>未染色为未划定地区</p>';$('taskTracker').hidden=true;
